import random

import cocotb
from cocotb.clock import Clock
from cocotb.triggers import FallingEdge, RisingEdge, Timer


CLK_NS = 10


def fields(word):
    sign = (word >> 31) & 1
    exponent = (word >> 23) & 255
    fraction = word & 0x7FFFFF
    return sign, exponent, fraction


def is_nan(word):
    sign, exponent, fraction = fields(word)
    return exponent == 255 and fraction != 0


def is_snan(word):
    sign, exponent, fraction = fields(word)
    return exponent == 255 and fraction != 0 and (fraction & 0x400000) == 0


def is_inf(word):
    sign, exponent, fraction = fields(word)
    return exponent == 255 and fraction == 0


def is_zero(word):
    sign, exponent, fraction = fields(word)
    return exponent == 0 and fraction == 0


def finite_parts(word):
    sign, exponent, fraction = fields(word)
    if exponent == 0:
        significand = fraction
        power = -149
    else:
        significand = (1 << 23) | fraction
        power = exponent - 127 - 23
    if sign:
        significand = -significand
    return significand, power


def compare_to_power(num, den, power, target_power):
    shift = power - target_power
    if shift >= 0:
        left = num << shift
        right = den
    else:
        left = num
        right = den << (-shift)
    if left < right:
        return -1
    if left > right:
        return 1
    return 0


def scaled_division(num, den, power, unit_power):
    shift = power - unit_power
    if shift >= 0:
        numerator = num << shift
        denominator = den
    else:
        numerator = num
        denominator = den << (-shift)
    return numerator // denominator, numerator % denominator, denominator


def round_integer(quotient, remainder, denominator, sign, mode):
    if remainder == 0:
        return quotient
    if mode == 0:
        twice = remainder << 1
        if twice > denominator or (twice == denominator and (quotient & 1)):
            return quotient + 1
    elif mode == 2 and sign == 0:
        return quotient + 1
    elif mode == 3 and sign == 1:
        return quotient + 1
    return quotient


def rounded_finite(num, den, power, mode):
    if num == 0:
        return 0, 0, 0, 0, 0

    sign = 1 if num < 0 else 0
    magnitude = abs(num)

    estimate = magnitude.bit_length() - den.bit_length() + power
    while compare_to_power(magnitude, den, power, estimate) < 0:
        estimate -= 1
    while compare_to_power(magnitude, den, power, estimate + 1) >= 0:
        estimate += 1

    if estimate >= -126:
        unit_power = estimate - 23
        quotient, remainder, denominator = scaled_division(
            magnitude, den, power, unit_power
        )
        rounded = round_integer(quotient, remainder, denominator, sign, mode)
        inexact = int(remainder != 0)

        if rounded >= (1 << 24):
            rounded >>= 1
            estimate += 1

        if estimate > 127:
            goes_to_infinity = (
                mode == 0
                or (mode == 2 and sign == 0)
                or (mode == 3 and sign == 1)
            )
            if goes_to_infinity:
                word = (sign << 31) | 0x7F800000
            else:
                word = (sign << 31) | 0x7F7FFFFF
            return word, 1, 1, 0, 0

        exponent_field = estimate + 127
        fraction = rounded - (1 << 23)
        word = (sign << 31) | (exponent_field << 23) | fraction
        return word, 0, inexact, 0, 0

    quotient, remainder, denominator = scaled_division(
        magnitude, den, power, -149
    )
    rounded = round_integer(quotient, remainder, denominator, sign, mode)
    inexact = int(remainder != 0)

    if rounded >= (1 << 23):
        word = (sign << 31) | 0x00800000
    else:
        word = (sign << 31) | rounded

    underflow = int(estimate < -126 and inexact)
    return word, 0, inexact, underflow, 0


def result_record(word, snan=0, qnan=0, ine=0, overflow=0,
                  underflow=0, div_by_zero=0, out_mask=0xFFFFFFFF,
                  flag_mask=None):
    flags = {
        "inf": int(is_inf(word)),
        "snan": int(snan),
        "qnan": int(qnan),
        "ine": int(ine),
        "overflow": int(overflow),
        "underflow": int(underflow),
        "zero": int(is_zero(word)),
        "div_by_zero": int(div_by_zero),
    }
    if flag_mask is None:
        flag_mask = set(flags)
    return word, out_mask, flags, flag_mask


def nan_record(opa, opb, invalid=False):
    nan_a = is_nan(opa)
    nan_b = is_nan(opb)
    if nan_a and not nan_b:
        sign = fields(opa)[0]
        out_mask = 0x7FFFFFFF
    elif nan_b and not nan_a:
        sign = fields(opb)[0]
        out_mask = 0x7FFFFFFF
    else:
        sign = 0
        out_mask = 0x7FFFFFFF
    word = (sign << 31) | 0x7FC00001
    return result_record(
        word,
        snan=int(is_snan(opa) or is_snan(opb)),
        qnan=1,
        out_mask=out_mask,
    )


def evaluate(op, mode, opa, opb):
    if op < 0 or op > 3:
        return None

    if is_nan(opa) or is_nan(opb):
        return nan_record(opa, opb)

    sign_a, exp_a, frac_a = fields(opa)
    sign_b, exp_b, frac_b = fields(opb)
    a_inf = is_inf(opa)
    b_inf = is_inf(opb)
    a_zero = is_zero(opa)
    b_zero = is_zero(opb)

    # The specification leaves every output unspecified for two infinities.
    if a_inf and b_inf:
        return None

    if op in (0, 1):
        effective_sign_b = sign_b ^ int(op == 1)
        if a_inf or b_inf:
            sign = sign_a if a_inf else effective_sign_b
            word = (sign << 31) | 0x7F800000
            return result_record(word)

        a_sig, a_power = finite_parts(opa)
        b_sig, b_power = finite_parts(opb)
        if op == 1:
            b_sig = -b_sig

        common_power = min(a_power, b_power)
        total = (a_sig << (a_power - common_power)) + (
            b_sig << (b_power - common_power)
        )
        if total == 0:
            if a_zero and b_zero and sign_a == effective_sign_b:
                sign = sign_a
            else:
                sign = int(mode == 3)
            word = sign << 31
            return result_record(word)

        word, overflow, ine, underflow, unused = rounded_finite(
            total, 1, common_power, mode
        )
        return result_record(
            word, ine=ine, overflow=overflow, underflow=underflow
        )

    result_sign = sign_a ^ sign_b

    if op == 2:
        if (a_inf and b_zero) or (b_inf and a_zero):
            return nan_record(opa, opb, invalid=True)
        if a_inf or b_inf:
            return result_record((result_sign << 31) | 0x7F800000)
        if a_zero or b_zero:
            return result_record(result_sign << 31)

        a_sig, a_power = finite_parts(opa)
        b_sig, b_power = finite_parts(opb)
        exact_num = abs(a_sig * b_sig)
        word, overflow, ine, underflow, unused = rounded_finite(
            exact_num, 1, a_power + b_power, mode
        )
        flags_to_check = set(result_record(word)[2])
        if ine == 0 and underflow == 1:
            flags_to_check.discard("underflow")
        return result_record(
            word,
            ine=ine,
            overflow=overflow,
            underflow=underflow,
            flag_mask=flags_to_check,
        )

    # Division.
    if a_inf:
        return result_record((result_sign << 31) | 0x7F800000)
    if b_inf:
        return result_record(result_sign << 31)
    if a_zero and b_zero:
        return nan_record(opa, opb, invalid=True)
    if b_zero:
        return result_record(
            (result_sign << 31) | 0x7F800000,
            div_by_zero=1,
        )
    if a_zero:
        return result_record(result_sign << 31)

    a_sig, a_power = finite_parts(opa)
    b_sig, b_power = finite_parts(opb)
    exact_num = abs(a_sig)
    exact_den = abs(b_sig)
    word, overflow, ine, underflow, unused = rounded_finite(
        exact_num, exact_den, a_power - b_power, mode
    )

    flags_to_check = set(result_record(word)[2])
    if exp_a == 0:
        flags_to_check.discard("ine")
    if ine == 0 and underflow == 1:
        flags_to_check.discard("underflow")
    return result_record(
        word,
        ine=ine,
        overflow=overflow,
        underflow=underflow,
        flag_mask=flags_to_check,
    )


async def run_vectors(dut, vectors):
    cocotb.start_soon(Clock(dut.clk, CLK_NS, "ns").start())
    dut.rmode.value = 0
    dut.fpu_op.value = 0
    dut.opa.value = 0
    dut.opb.value = 0

    vectors = list(vectors)
    vectors.extend([(0, 0, 0, 0)] * 3)

    for index, (op, mode, opa, opb) in enumerate(vectors):
        await FallingEdge(dut.clk)
        dut.fpu_op.value = op
        dut.rmode.value = mode
        dut.opa.value = opa
        dut.opb.value = opb

        await RisingEdge(dut.clk)
        await Timer(1, unit="ns")

        output_index = index - 3
        if output_index < 0:
            continue

        expected = evaluate(*vectors[output_index])
        if expected is None:
            continue

        word, out_mask, flags, flag_mask = expected
        observed = int(dut.out.value)
        assert (observed & out_mask) == (word & out_mask), (
            f"out mismatch for {vectors[output_index]}: "
            f"got 0x{observed:08x}, expected 0x{word:08x}"
        )

        for name in flag_mask:
            value = int(getattr(dut, name).value)
            assert value == flags[name], (
                f"{name} mismatch for {vectors[output_index]}: "
                f"got {value}, expected {flags[name]}"
            )


@cocotb.test()
