    vectors.extend([
        (0, 0, 0x3F800000, 0x33800000),
        (0, 0, 0x3F800001, 0x33800000),
        (0, 2, 0x3F800000, 0x33800000),
        (0, 3, 0x3F800000, 0xB3800000),
        (0, 3, 0x3F800000, 0xBF800000),
        (1, 0, 0x3F800000, 0x3F800000),
        (2, 0, 0x3FC00000, 0x3FC00000),
        (3, 0, 0x3F800000, 0x40400000),
        (3, 0, 0x00800000, 0x40000000),
        (3, 1, 0x7F7FFFFF, 0x3F000000),
    ])

    await run_vectors(dut, vectors)


@cocotb.test()
async def randomized_finite_arithmetic(dut):
    random.seed(7341)
