        opa = random.getrandbits(32)
        opb = random.getrandbits(32)
        if ((opa >> 23) & 255) == 255:
            opa &= 0x807FFFFF
        if ((opb >> 23) & 255) == 255:
            opb &= 0x807FFFFF

        for op in range(4):
            vectors.append((op, random.randrange(4), opa, opb))

    await run_vectors(dut, vectors)
