    dut.fpu_op.value = 0
    dut.opa.value = 0
    dut.opb.value = 0
    await FallingEdge(dut.clk)


def classify(bits):
    exponent = (bits >> 23) & 0xFF
    fraction = bits & 0x7FFFFF
    if exponent == 0xFF:
        if fraction == 0:
            return "inf"
        return "snan" if (fraction & 0x400000) == 0 else "qnan"
    if exponent == 0 and fraction == 0:
        return "zero"
    return "finite"


def finite_ratio(bits):
    sign = -1 if (bits >> 31) else 1
    exponent = (bits >> 23) & 0xFF
    fraction = bits & 0x7FFFFF
    if exponent == 0:
        significand = fraction
        shift = -149
    else:
        significand = (1 << 23) | fraction
        shift = exponent - 150

    numerator = sign * significand
    if shift >= 0:
        return numerator << shift, 1
    return numerator, 1 << (-shift)


def floor_log2_ratio(numerator, denominator):
    exponent = numerator.bit_length() - denominator.bit_length()
    if exponent >= 0:
        if numerator < (denominator << exponent):
            exponent -= 1
    elif (numerator << (-exponent)) < denominator:
        exponent -= 1
    return exponent


def rounded_integer(numerator, denominator, unit_exponent, sign, mode,
                    subnormal_division_tie=False):
    if unit_exponent >= 0:
        scaled_numerator = numerator
        scaled_denominator = denominator << unit_exponent
    else:
        scaled_numerator = numerator << (-unit_exponent)
        scaled_denominator = denominator

    quotient, remainder = divmod(scaled_numerator, scaled_denominator)
    increment = False

    if remainder:
        if mode == 0:
            twice_remainder = remainder << 1
            if twice_remainder > scaled_denominator:
                increment = True
            elif twice_remainder == scaled_denominator:
                if subnormal_division_tie and quotient == 0:
                    increment = False
                elif subnormal_division_tie:
                    increment = True
                else:
                    increment = (quotient & 1) != 0
        elif mode == 2:
            increment = sign > 0
        elif mode == 3:
            increment = sign < 0

    return quotient + (1 if increment else 0), remainder != 0


