    exponent = (bits >> 23) & 0xFF
    fraction = bits & 0x7FFFFF
    if exponent == 0xFF:
        if fraction == 0:
            return "inf"
        if fraction & 0x400000:
            return "qnan"
        return "snan"
    if exponent == 0 and fraction == 0:
        return "zero"
    return "finite"


def finite_ratio(bits):
    """Return signed numerator and positive denominator for a finite operand."""
    exponent = (bits >> 23) & 0xFF
    fraction = bits & 0x7FFFFF
    if exponent == 0:
        significand = fraction
        power = -149
    else:
        significand = (1 << 23) | fraction
        power = exponent - 127 - 23
    if sign_bit(bits):
        significand = -significand
    if power >= 0:
        return significand << power, 1
    return significand, 1 << (-power)


def floor_log2_ratio(numerator, denominator):
    exponent = numerator.bit_length() - denominator.bit_length()
    if exponent >= 0:
        if numerator < (denominator << exponent):
            exponent -= 1
    elif (numerator << (-exponent)) < denominator:
        exponent -= 1
    return exponent


def special_result(bits, mask, flags):
    return bits, mask, tuple(flags[name] for name in FLAG_NAMES)


