    flags = {
        "inf": 0,
        "snan": int(bool(snan)),
        "qnan": 1,
        "ine": 0,
        "overflow": 0,
        "underflow": 0,
        "zero": 0,
        "div_by_zero": 0,
    }
    bits = (sign << 31) | 0x7FC00001
    mask = 0x7FFFFFFF if ignore_sign else 0xFFFFFFFF
    return special_result(bits, mask, flags)


