    flags = {
        "inf": 1,
        "snan": 0,
        "qnan": 0,
        "ine": 0,
        "overflow": 0,
        "underflow": 0,
        "zero": 0,
        "div_by_zero": div_by_zero,
    }
    return special_result((sign << 31) | 0x7F800000, 0xFFFFFFFF, flags)


