    dut.rmode.value = 0
    dut.fpu_op.value = 0
    dut.opa.value = 0
    dut.opb.value = 0
    await with_timeout(FallingEdge(dut.clk), 100, "ns")


def is_zero(bits):
    return (bits & 0x7FFFFFFF) == 0


def is_inf(bits):
    return (bits & 0x7FFFFFFF) == 0x7F800000


def is_nan(bits):
    return (bits & 0x7F800000) == 0x7F800000 and (bits & 0x7FFFFF) != 0


def is_snan(bits):
    return is_nan(bits) and (bits & 0x400000) == 0


def finite_ratio(bits):
    """Return the exact signed value as numerator / positive denominator."""
    sign = -1 if bits >> 31 else 1
    exp = (bits >> 23) & 0xFF
    frac = bits & 0x7FFFFF
    if exp == 0:
        sig = frac
        power = -149
    else:
        sig = (1 << 23) | frac
        power = exp - 127 - 23

    numerator = sign * sig
    if power >= 0:
        return numerator << power, 1
    return numerator, 1 << (-power)


def floor_log2_ratio(numerator, denominator):
    """floor(log2(numerator / denominator)) for positive integers."""
    exponent = numerator.bit_length() - denominator.bit_length()
    if exponent >= 0:
        if numerator < (denominator << exponent):
            exponent -= 1
    elif (numerator << (-exponent)) < denominator:
        exponent -= 1
    return exponent


def scaled_division(numerator, denominator, power):
    """Return floor((numerator / denominator) / 2**power) and remainder."""
    if power >= 0:
        numerator, denominator = numerator, denominator << power
    else:
        numerator, denominator = numerator << (-power), denominator
    return divmod(numerator, denominator)


def rounded_integer(numerator, denominator, sign, mode, div_tie_away=False):
    """Round a positive rational integer quotient according to the FPU mode."""
    quotient, remainder = divmod(numerator, denominator)
    if remainder == 0:
        return quotient, False

    increment = False
    if mode == 0:
        twice = remainder << 1
        if twice > denominator:
            increment = True
        elif twice == denominator:
            if div_tie_away and quotient >= 1:
                increment = True
            else:
                increment = (quotient & 1) != 0
    elif mode == 2:
        increment = sign > 0
    elif mode == 3:
        increment = sign < 0

    if increment:
        quotient += 1
    return quotient, True


def round_finite(numerator, denominator, mode, op):
    """Return (bits, inexact, overflow, tiny) for an exact finite rational."""
    if numerator == 0:
        return 0, False, False, False

    sign = -1 if numerator < 0 else 1
    magnitude = abs(numerator)
    exponent = floor_log2_ratio(magnitude, denominator)
    tiny = (magnitude << 126) < denominator

    if exponent < -126:
        scaled_num = magnitude << 149
        quotient, inexact = rounded_integer(
            scaled_num,
            denominator,
            sign,
            mode,
            div_tie_away=(op == 3 and mode == 0),
        )
        if quotient == 0:
            bits = 0
        else:
            # This also encodes the carry from the largest subnormal to min-normal.
            bits = quotient
    else:
        power = exponent - 23
        scaled_num, scaled_den = scaled_division(magnitude, denominator, power)
        quotient, inexact = rounded_integer(scaled_num, scaled_den, sign, mode)

        if quotient >= (1 << 24):
            quotient >>= 1
            exponent += 1

        if exponent > 127:
            overflow = True
            to_infinity = (
                mode == 0
                or (mode == 2 and sign > 0)
                or (mode == 3 and sign < 0)
            )
            if to_infinity:
                bits = 0x7F800000
            else:
                bits = 0x7F7FFFFF
            if sign < 0:
                bits |= 0x80000000
