        "out": bits,
        "check_nan_sign": check_nan_sign,
        "inf": int(is_inf(bits)),
        "snan": int(snan),
        "qnan": int(qnan),
        "ine": int(ine),
        "overflow": int(overflow),
        "underflow": int(underflow),
