        nb, db = finite_ratio(opb)
        if op == 1:
            nb = -nb
        numerator = na * db + nb * da
        denominator = da * db

        if numerator == 0:
            # Same effective zero signs retain their sign; cancellation uses
            # negative zero only for round-toward-minus-infinity.
            sign_a = opa >> 31
            effective_sign_b = (opb >> 31) ^ op
            if zero_a and zero_b and sign_a == effective_sign_b:
                sign = sign_a
            else:
                sign = int(mode == 3)
            return special_result(sign << 31, snan, False)

