            return special_result(0x7FC00001, snan, True, check_nan_sign=False)
        if inf_a or inf_b:
            return special_result((sign << 31) | 0x7F800000, snan, False)
        if zero_a or zero_b:
            return special_result(sign << 31, snan, False)

        na, da = finite_ratio(opa)
        nb, db = finite_ratio(opb)
        numerator = na * nb
        denominator = da * db

    else:  # op == 3, division
        sign = (opa >> 31) ^ (opb >> 31)
        if zero_a and zero_b:
            return special_result(0x7FC00001, snan, True, check_nan_sign=False)
        if inf_a:
            return special_result((sign << 31) | 0x7F800000, snan, False)
        if inf_b:
            return special_result(sign << 31, snan, False)
        if zero_b:
