                return special_result(0x7FC00001, snan, True, check_nan_sign=False)
            return special_result(
                (sign << 31) | 0x7F800000,
                snan,
                False,
                div_by_zero=True,
            )
        if zero_a:
            return special_result(sign << 31, snan, False)

        na, da = finite_ratio(opa)
        nb, db = finite_ratio(opb)
        numerator = na * db
        denominator = da * nb
        if denominator < 0:
            numerator = -numerator
            denominator = -denominator

    if denominator < 0:
        numerator = -numerator
        denominator = -denominator

    bits, ine, overflow, tiny = round_finite(numerator, denominator, mode, op)
    exact = not ine
    underflow = tiny and ine
    return {
        "out": bits,
        "check_nan_sign": True,
        "inf": int(is_inf(bits)),
        "snan": int(snan),
        "qnan": int(is_nan(bits)),
        "ine": int(ine or overflow),
        "overflow": int(overflow),
        "underflow": int(underflow),
        "zero": int(is_zero(bits)),
        "div_by_zero": 0,
        "skip_ine": (op == 3 and ((opa >> 23) & 0xFF) == 0 and not zero_a),
        "skip_underflow": (op in (2, 3) and tiny and exact),
    }


def make_vectors():
    vectors = []

    def add(op, mode, a, b):
        vectors.append((op, mode, a, b))

    # Basic arithmetic, exact cancellation, signed zero, and rounding modes.
    constants = [
        0x00000000, 0x80000000, 0x00000001, 0x00000002,
        0x007FFFFF, 0x00800000, 0x3F800000, 0xBF800000,
        0x40000000, 0xC0000000, 0x3F000000, 0xBF000000,
        0x7F7FFFFF, 0xFF7FFFFF, 0x7F800000, 0xFF800000,
        0x7FC12345, 0xFFC54321, 0x7F800001, 0xFF800001,
    ]
    for mode in range(4):
        for op in range(4):
            for a, b in [
                (0x3F800000, 0x3F800000),
                (0x3F800000, 0xBF800000),
                (0x80000000, 0x80000000),
                (0x00000000, 0x80000000),
                (0x00000001, 0x3F800000),
                (0x00800000, 0x40000000),
                (0x7F7FFFFF, 0x40000000),
                (0x3F800000, 0x00000000),
                (0x00000000, 0x00000000),
                (0x7F800000, 0x3F800000),
                (0x3F800000, 0x7F800000),
                (0x7F800001, 0x3F800000),
                (0x3F800000, 0xFFC12345),
            ]:
                add(op, mode, a, b)

    # Exercise classes and operand ordering while avoiding the unspecified
    # both-infinity case.
    for mode in range(4):
        for op in range(4):
            for a in constants:
                for b in constants:
                    if is_inf(a) and is_inf(b):
                        continue
                    add(op, mode, a, b)

    rng = random.Random(24681357)
    for _ in range(700):
        op = rng.randrange(4)
        mode = rng.randrange(4)

        def random_operand():
