            if choice == 0:
                return rng.choice(constants)
            if choice == 1:
                return rng.randrange(0x00800000)  # positive subnormal or zero
            if choice == 2:
                return 0x80000000 | rng.randrange(0x00800000)
            exp = rng.randrange(1, 255)
            frac = rng.randrange(1 << 23)
            sign = rng.randrange(2) << 31
            return sign | (exp << 23) | frac

        a = random_operand()
        b = random_operand()
        if is_inf(a) and is_inf(b):
            b = 0x3F800000
        add(op, mode, a, b)

    return vectors


