async def fpu_behavior(dut):
    await start(dut)
    vectors = make_vectors()
    idle = (0, 0, 0, 0)

    for cycle in range(len(vectors) + 3):
        await with_timeout(FallingEdge(dut.clk), 100, "ns")
        if cycle < len(vectors):
