                f"out=0x{actual_out:08x}, expected=0x{expected['out']:08x}"
            )
        else:
            assert (actual_out & 0x7FFFFFFF) == 0x7FC00001, (
                f"op={op} mode={mode} opa=0x{opa:08x} opb=0x{opb:08x}: "
                f"NaN magnitude was 0x{actual_out & 0x7FFFFFFF:08x}"
            )

        for flag in (
            "inf", "snan", "qnan", "ine", "overflow",
            "underflow", "zero", "div_by_zero",
        ):
            if flag == "ine" and expected.get("skip_ine", False):
                continue
            if flag == "underflow" and expected.get("skip_underflow", False):
                continue
            actual = int(dut[flag].value)
            assert actual == expected[flag], (
                f"op={op} mode={mode} opa=0x{opa:08x} opb=0x{opb:08x}: "
                f"{flag}={actual}, expected={expected[flag]}"
            )
