            if normal_exp > 127:
                # Normally handled by the overflow test above.
                rounds_away = (mode == 2 and sign == 0) or (mode == 3 and sign == 1)
                bits = signbit | (0x7F800000 if mode == 0 or rounds_away else MAX_FINITE)
            else:
                exponent_field = normal_exp + 127
                fraction_field = rounded - (1 << 23)
                bits = signbit | (exponent_field << 23) | (fraction_field & 0x7FFFFF)

    tiny = compare_scaled(magnitude, denominator, 1, -126) < 0
    underflow = int(tiny and inexact)
    flags = {
        "inf": int((bits & 0x7FFFFFFF) == 0x7F800000),
        "snan": 0,
        "qnan": 0,
        "ine": int(inexact),
        "overflow": 0,
        "underflow": underflow,
        "zero": int((bits & 0x7FFFFFFF) == 0),
        "div_by_zero": 0,
    }

    # The specification leaves these cases unspecified.
    if op == 3 and classify(_current_opa[0]) == "finite" and (
        ((_current_opa[0] >> 23) & 0xFF) == 0
    ):
        flags["ine"] = None
    if tiny and not inexact and op in (2, 3):
        flags["underflow"] = None

    return bits & MASK32, flags


_current_opa = [0]


def model(op, mode, opa, opb):
    kind_a = classify(opa)
    kind_b = classify(opb)
    sign_a = opa >> 31
    sign_b = opb >> 31
    nan_a = kind_a in ("qnan", "snan")
    nan_b = kind_b in ("qnan", "snan")
    snan = int(kind_a == "snan" or kind_b == "snan")

    def nan_result(sign=None):
        if sign is None:
            sign = 0
        return (CANONICAL_NAN | (sign << 31), {
            "inf": 0, "snan": snan, "qnan": 1, "ine": 0,
            "overflow": 0, "underflow": 0, "zero": 0,
            "div_by_zero": 0,
        })

    # Both-infinity cases are explicitly unspecified.
    if kind_a == "inf" and kind_b == "inf":
        return None

    if nan_a or nan_b:
        if nan_a and not nan_b:
            return nan_result(sign_a)
        if nan_b and not nan_a:
            return nan_result(sign_b)
        return nan_result()

    if op == 0 or op == 1:
        effective_b_sign = sign_b ^ (1 if op == 1 else 0)
        if kind_a == "inf":
            return ((sign_a << 31) | 0x7F800000, {
                "inf": 1, "snan": 0, "qnan": 0, "ine": 0,
                "overflow": 0, "underflow": 0, "zero": 0,
                "div_by_zero": 0,
            })
        if kind_b == "inf":
            return ((effective_b_sign << 31) | 0x7F800000, {
                "inf": 1, "snan": 0, "qnan": 0, "ine": 0,
                "overflow": 0, "underflow": 0, "zero": 0,
                "div_by_zero": 0,
            })

        na, da = finite_fraction(opa)
        nb, db = finite_fraction(opb)
        if op == 1:
            nb = -nb
        numerator = na * db + nb * da
        denominator = da * db

        if numerator == 0:
            # Same-sign zero operands retain their sign; exact cancellation
            # has the rounding-mode-dependent IEEE zero sign.
            if na == 0 and nb == 0 and sign_a == effective_b_sign:
                zero_sign = sign_a
            else:
                zero_sign = int(mode == 3)
            return round_finite(0, denominator, zero_sign, mode, op)
        return round_finite(numerator, denominator, 0, mode, op)

    if op == 2:
        if (kind_a == "inf" and kind_b == "zero") or (
            kind_b == "inf" and kind_a == "zero"
        ):
            return nan_result()
        sign = sign_a ^ sign_b
        if kind_a == "inf" or kind_b == "inf":
            return ((sign << 31) | 0x7F800000, {
                "inf": 1, "snan": 0, "qnan": 0, "ine": 0,
                "overflow": 0, "underflow": 0, "zero": 0,
                "div_by_zero": 0,
            })
        na, da = finite_fraction(opa)
        nb, db = finite_fraction(opb)
        return round_finite(na * nb, da * db, sign, mode, op)

    if op == 3:
        if kind_a == "zero" and kind_b == "zero":
            return nan_result()
        sign = sign_a ^ sign_b
        if kind_a == "inf":
            return ((sign << 31) | 0x7F800000, {
                "inf": 1, "snan": 0, "qnan": 0, "ine": 0,
                "overflow": 0, "underflow": 0, "zero": 0,
                "div_by_zero": 0,
            })
        if kind_b == "inf":
            return round_finite(0, 1, sign, mode, op)
        if kind_b == "zero":
            if kind_a == "finite":
                na, da = finite_fraction(opa)
                if na != 0:
                    return ((sign << 31) | 0x7F800000, {
                        "inf": 1, "snan": 0, "qnan": 0, "ine": 0,
                        "overflow": 0, "underflow": 0, "zero": 0,
                        "div_by_zero": 1,
                    })
            return round_finite(0, 1, sign, mode, op)

        na, da = finite_fraction(opa)
        nb, db = finite_fraction(opb)
        return round_finite(na * db, da * nb, sign, mode, op)

    return None


def make_vectors():
    vectors = []
    specials = [
        0x00000000, 0x80000000, 0x00000001, 0x00000002,
        0x007FFFFF, 0x00800000, 0x00800001,
        0x3F800000, 0x3F800001, 0x3F000000, 0xBF800000,
        0x7F7FFFFF, 0xFF7FFFFF, 0x7F800000, 0xFF800000,
        0x7FC12345, 0xFFC54321, 0x7F800001, 0xFF800002,
    ]

    # Exercise every operation and rounding mode on important class pairs.
    pairs = [
        (0x00000000, 0x00000000), (0x80000000, 0x80000000),
        (0x00000000, 0x80000000), (0x3F800000, 0x3F800000),
        (0x3F800000, 0xBF800000), (0x00000001, 0x00000001),
        (0x007FFFFF, 0x00800000), (0x7F7FFFFF, 0x7F7FFFFF),
        (0x7F800000, 0x3F800000), (0xFF800000, 0x3F800000),
        (0x3F800000, 0x00000000), (0x00000000, 0x00000000),
        (0x00000001, 0x40000000), (0x00800000, 0x40000000),
        (0x3F800000, 0x40400000), (0x7FC12345, 0x3F800000),
        (0x3F800000, 0xFFC12345), (0x7F800001, 0x3F800000),
        (0x00000000, 0x7F800000), (0x7F800000, 0x00000000),
        (0x00000000, 0x3F800000), (0x3F800000, 0x7F800000),
        (0x00800000, 0x3F000000), (0x7F7FFFFF, 0x40000000),
    ]
    for op in range(4):
        for mode in range(4):
            for a, b in pairs:
                vectors.append((op, mode, a, b))

    # Pairwise class coverage across all supported input categories.
    for op in range(4):
        for mode in range(4):
            for index, a in enumerate(specials):
                b = specials[(index * 7 + 3) % len(specials)]
                vectors.append((op, mode, a, b))

    from random import Random
    rng = Random(0x5EED1234)
    for _ in range(500):
        op = rng.randrange(4)
        mode = rng.randrange(4)
        a = rng.getrandbits(32)
        b = rng.getrandbits(32)
        # Keep random inputs finite so the randomized arithmetic also covers
        # a broad range of normal and subnormal exponents.
        if ((a >> 23) & 0xFF) == 0xFF:
            a &= 0x807FFFFF
        if ((b >> 23) & 0xFF) == 0xFF:
            b &= 0x807FFFFF
        vectors.append((op, mode, a, b))

    return vectors


@cocotb.test()
async def arithmetic_and_pipeline(dut):
    await start(dut)

    vectors = make_vectors()
    expected_queue = []

    flag_ports = [
        ("inf", dut.inf),
        ("snan", dut.snan),
        ("qnan", dut.qnan),
        ("ine", dut.ine),
        ("overflow", dut.overflow),
        ("underflow", dut.underflow),
        ("zero", dut.zero),
        ("div_by_zero", dut.div_by_zero),
    ]

    for op, mode, opa, opb in vectors:
        dut.fpu_op.value = op
        dut.rmode.value = mode
        dut.opa.value = opa
        dut.opb.value = opb
        expected_queue.append(model(op, mode, opa, opb))

        await RisingEdge(dut.clk)
        await ReadOnly()

        # The result for the first sampled edge appears after the fourth
        # rising edge: three complete pipeline clocks later.
        if len(expected_queue) > 3:
            expected = expected_queue.pop(0)
            if expected is not None:
                actual_out = int(dut.out.value)
                assert actual_out == expected[0], (
                    f"op={op} mode={mode} opa=0x{opa:08x} opb=0x{opb:08x}: "
                    f"out=0x{actual_out:08x}, expected=0x{expected[0]:08x}"
                )
                for name, port in flag_ports:
                    wanted = expected[1][name]
                    if wanted is not None:
                        actual = int(port.value)
                        assert actual == wanted, (
                            f"op={op} mode={mode} opa=0x{opa:08x} "
                            f"opb=0x{opb:08x}: {name}={actual}, expected={wanted}"
                        )

    # Supply three more operations to drain the pipeline.
    for _ in range(3):
        dut.fpu_op.value = 0
        dut.rmode.value = 0
        dut.opa.value = 0x3F800000
        dut.opb.value = 0x3F800000
        expected_queue.append(model(0, 0, 0x3F800000, 0x3F800000))

        await RisingEdge(dut.clk)
        await ReadOnly()

        if len(expected_queue) > 3:
            expected = expected_queue.pop(0)
            if expected is not None:
                actual_out = int(dut.out.value)
                assert actual_out == expected[0]
                for name, port in flag_ports:
                    wanted = expected[1][name]
                    if wanted is not None:
                        assert int(port.value) == wanted
